// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetChats Список чатов пользователя.
	// (GET /chats)
	GetChats(ctx context.Context, request GetChatsRequestObject) (GetChatsResponseObject, error)
	// CreateChat Создать чат.
	// (POST /chats)
	CreateChat(ctx context.Context, request CreateChatRequestObject) (CreateChatResponseObject, error)
	// DeleteChat Удаление чата.
	// (DELETE /chats/{id})
	DeleteChat(ctx context.Context, request DeleteChatRequestObject) (DeleteChatResponseObject, error)
	// GetChatInfo Получение информации о чате.
	// (GET /chats/{id})
	GetChatInfo(ctx context.Context, request GetChatInfoRequestObject) (GetChatInfoResponseObject, error)
	// GetChatMembers Участники чата.
	// (GET /chats/{id}/members)
	GetChatMembers(ctx context.Context, request GetChatMembersRequestObject) (GetChatMembersResponseObject, error)
	// AddChatMember Добавить участника.
	// (POST /chats/{id}/members)
	AddChatMember(ctx context.Context, request AddChatMemberRequestObject) (AddChatMemberResponseObject, error)
	// DeleteChatMember Удаление участника.
	// (DELETE /chats/{id}/members/{userId})
	DeleteChatMember(ctx context.Context, request DeleteChatMemberRequestObject) (DeleteChatMemberResponseObject, error)
	// GetMessages История сообщений чата.
	// (GET /chats/{id}/messages)
	GetMessages(ctx context.Context, request GetMessagesRequestObject) (GetMessagesResponseObject, error)
	// SendMessage Отправка сообщения.
	// (POST /chats/{id}/messages)
	SendMessage(ctx context.Context, request SendMessageRequestObject) (SendMessageResponseObject, error)
	// EditProfile Изменение настроек профиля пользователя.
	// (PATCH /profile)
	EditProfile(ctx context.Context, request EditProfileRequestObject) (EditProfileResponseObject, error)
	// LoginSession Создать сессию.
	// (POST /sessions)
	LoginSession(ctx context.Context, request LoginSessionRequestObject) (LoginSessionResponseObject, error)
	// InvalidateSession Инвалидировать сессию.
	// (DELETE /sessions/{id})
	InvalidateSession(ctx context.Context, request InvalidateSessionRequestObject) (InvalidateSessionResponseObject, error)
	// RefreshToken Обновление токена.
	// (POST /tokens)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// SearchUsers Поиск пользователей по юзернейму.
	// (GET /users)
	SearchUsers(ctx context.Context, request SearchUsersRequestObject) (SearchUsersResponseObject, error)
	// RegisterUser Создание пользователя.
	// (POST /users)
	RegisterUser(ctx context.Context, request RegisterUserRequestObject) (RegisterUserResponseObject, error)
	// GetUserInfo Информация о пользователе.
	// (GET /users/{id})
	GetUserInfo(ctx context.Context, request GetUserInfoRequestObject) (GetUserInfoResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

